//! ES|QL commands, functions, and operators from `data/catalogs/esql/`.
//!
//! The TOML is generated by `scripts/engine/sync_esql_catalog.py` from Elastic's
//! own definition JSON, the docs `applies_to` lifecycle, and each release
//! branch's grammar and definitions (`versions`). Each file is read once per
//! process, item by item ([`opentide_core::catalog`]).

use crate::version::Availability;
use opentide_core::suggest;
use std::sync::OnceLock;

pub use crate::catalog_model::{CommandRow, FunctionRow, OperatorRow, ParamRow, TypeRow};

impl CommandRow {
    pub fn availability(&self) -> Option<Availability> {
        self.prepared().available
    }

    /// The `stack` lifecycle.
    pub fn lifecycle(&self) -> Lifecycle {
        self.prepared().lifecycle
    }

    fn read(&self) -> Prepared {
        Prepared::of(self.versions.as_deref(), &self.stack)
    }

    fn prepared(&self) -> Prepared {
        static PREPARED: OnceLock<Vec<Prepared>> = OnceLock::new();
        bundled(&Catalog::cached().commands, self, &PREPARED, Self::read)
    }
}

impl FunctionRow {
    pub fn availability(&self) -> Option<Availability> {
        self.prepared().available
    }

    /// The `stack` lifecycle.
    pub fn lifecycle(&self) -> Lifecycle {
        self.prepared().lifecycle
    }

    fn read(&self) -> Prepared {
        Prepared::of(self.versions.as_deref(), &self.stack)
    }

    fn prepared(&self) -> Prepared {
        static PREPARED: OnceLock<Vec<Prepared>> = OnceLock::new();
        bundled(&Catalog::cached().functions, self, &PREPARED, Self::read)
    }
}

impl TypeRow {
    pub fn availability(&self) -> Availability {
        static PREPARED: OnceLock<Vec<Availability>> = OnceLock::new();
        bundled(&Catalog::cached().types, self, &PREPARED, |row| {
            Availability::from_versions(&row.versions)
        })
    }
}

/// What a row's `versions` and `stack` say.
#[derive(Debug, Clone, Copy)]
struct Prepared {
    available: Option<Availability>,
    lifecycle: Lifecycle,
}

impl Prepared {
    fn of(versions: Option<&[String]>, stack: &str) -> Self {
        Self {
            available: versions.map(Availability::from_versions),
            lifecycle: Lifecycle::parse(stack),
        }
    }
}

/// `read(row)`, from `prepared` when `row` is one of `rows`, the bundled
/// catalog's: read once for all its rows on first use (ADR 0014 §2). Any other
/// row (a clone, a caller's own) is read as it is now.
fn bundled<T, P: Copy>(
    rows: &'static [T],
    row: &T,
    prepared: &'static OnceLock<Vec<P>>,
    read: fn(&T) -> P,
) -> P {
    match index_in(rows, row) {
        Some(i) => prepared.get_or_init(|| rows.iter().map(read).collect())[i],
        None => read(row),
    }
}

/// The index of `row` in `rows` when it is one of them (the same address,
/// not an equal value).
fn index_in<T>(rows: &[T], row: &T) -> Option<usize> {
    let size = std::mem::size_of::<T>().max(1);
    let offset = std::ptr::from_ref(row)
        .addr()
        .checked_sub(rows.as_ptr().addr())?;
    let i = offset / size;
    rows.get(i).filter(|r| std::ptr::eq(*r, row)).map(|_| i)
}

#[derive(Debug)]
pub struct Catalog {
    pub commands: Vec<CommandRow>,
    pub functions: Vec<FunctionRow>,
    pub operators: Vec<OperatorRow>,
    pub types: Vec<TypeRow>,
    /// Release branches the `versions` lists were read from.
    pub branches: Vec<String>,
}

/// What `build.rs` stores (#1743), parsed once at build time: the release branches, the commands,
/// the functions, the operators and the cast types.
type Model = (
    Vec<String>,
    Vec<CommandRow>,
    Vec<FunctionRow>,
    Vec<OperatorRow>,
    Vec<TypeRow>,
);

/// The catalogs, pre-parsed by `build.rs` and decoded on first use.
fn model() -> Model {
    opentide_dataset::compiled_value("esql-catalog", opentide_dataset::blob!("esql-catalog"))
}

impl Catalog {
    pub fn cached() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            let (branches, commands, functions, operators, types) = model();
            Catalog {
                commands,
                functions,
                operators,
                types,
                branches,
            }
        })
    }

    /// Whether this is the bundled catalog, whose indexes are built once
    /// (ADR 0014 §2); any other catalog is scanned.
    fn is_bundled(&self) -> bool {
        std::ptr::eq(self, Self::cached())
    }

    /// A command by its canonical lower-case name (`stats`, `lookup join`).
    pub fn command(&self, name: &str) -> Option<&CommandRow> {
        if self.is_bundled() {
            static INDEX: OnceLock<NameIndex> = OnceLock::new();
            let index = INDEX
                .get_or_init(|| NameIndex::new(self.commands.iter().map(|c| [c.name.as_str()])));
            return index.find(name).map(|i| &self.commands[i]);
        }
        count_scan();
        self.commands
            .iter()
            .find(|c| c.name.eq_ignore_ascii_case(name))
    }

    /// Function names are case-insensitive; aliases resolve to their function.
    pub fn function(&self, name: &str) -> Option<&FunctionRow> {
        if self.is_bundled() {
            static INDEX: OnceLock<NameIndex> = OnceLock::new();
            let index = INDEX.get_or_init(|| {
                NameIndex::new(self.functions.iter().map(|f| {
                    std::iter::once(f.name.as_str()).chain(f.aliases.iter().map(String::as_str))
                }))
            });
            return index.find(name).map(|i| &self.functions[i]);
        }
        count_scan();
        self.functions.iter().find(|f| {
            f.name.eq_ignore_ascii_case(name)
                || f.aliases.iter().any(|a| a.eq_ignore_ascii_case(name))
        })
    }

    /// A `::type` cast target; names are case-insensitive.
    pub fn cast_type(&self, name: &str) -> Option<&TypeRow> {
        if self.is_bundled() {
            static INDEX: OnceLock<NameIndex> = OnceLock::new();
            let index =
                INDEX.get_or_init(|| NameIndex::new(self.types.iter().map(|t| [t.name.as_str()])));
            return index.find(name).map(|i| &self.types[i]);
        }
        count_scan();
        self.types
            .iter()
            .find(|t| t.name.eq_ignore_ascii_case(name))
    }

    /// The cast type `name` most likely means ([`opentide_core::suggest`]).
    pub fn suggest_type(&self, name: &str) -> Option<String> {
        let names = || self.types.iter().map(|t| t.name.as_str());
        if self.is_bundled() {
            static SUGGESTED: OnceLock<Suggested> = OnceLock::new();
            return SUGGESTED
                .get_or_init(|| Suggested::new(names()))
                .closest(name);
        }
        count_scan();
        suggest::closest(name, names()).map(str::to_string)
    }

    pub fn operator(&self, symbol: &str) -> Option<&OperatorRow> {
        self.operators
            .iter()
            .find(|o| o.operator.eq_ignore_ascii_case(symbol))
    }

    /// The command `name` most likely means, for `esql_unknown_command`
    /// ([`opentide_core::suggest`]).
    pub fn suggest_command(&self, name: &str) -> Option<String> {
        let names = || {
            self.commands
                .iter()
                .filter(|c| !c.snapshot_only && c.alias_of.is_none())
                .map(|c| c.name.as_str())
        };
        if self.is_bundled() {
            static SUGGESTED: OnceLock<Suggested> = OnceLock::new();
            return SUGGESTED
                .get_or_init(|| Suggested::new(names()))
                .closest(name);
        }
        count_scan();
        suggest::closest(name, names()).map(str::to_string)
    }

    /// The function `name` most likely means ([`opentide_core::suggest`]).
    pub fn suggest_function(&self, name: &str) -> Option<String> {
        let names = || {
            self.functions
                .iter()
                .filter(|f| !f.snapshot_only)
                .map(|f| f.name.as_str())
        };
        if self.is_bundled() {
            static SUGGESTED: OnceLock<Suggested> = OnceLock::new();
            return SUGGESTED
                .get_or_init(|| Suggested::new(names()))
                .closest(name);
        }
        count_scan();
        suggest::closest(name, names()).map(str::to_string)
    }
}

/// The rows of a catalog by name, ASCII case folded: what a scan with
/// `eq_ignore_ascii_case` finds, the first row holding a name winning.
struct NameIndex(std::collections::HashMap<String, usize>);

impl NameIndex {
    fn new<'a, N: IntoIterator<Item = &'a str>>(rows: impl Iterator<Item = N>) -> Self {
        let mut index = std::collections::HashMap::new();
        for (i, names) in rows.enumerate() {
            for name in names {
                index.entry(name.to_ascii_lowercase()).or_insert(i);
            }
        }
        Self(index)
    }

    fn find(&self, name: &str) -> Option<usize> {
        if name.bytes().any(|b| b.is_ascii_uppercase()) {
            self.0.get(&name.to_ascii_lowercase()).copied()
        } else {
            self.0.get(name).copied()
        }
    }
}

/// Suggestion candidates prepared once ([`suggest::Candidates`]): what
/// [`suggest::closest`] ranks, without preparing every candidate per call.
struct Suggested {
    names: Vec<String>,
    candidates: suggest::Candidates,
}

impl Suggested {
    fn new<'a>(names: impl Iterator<Item = &'a str>) -> Self {
        let names: Vec<String> = names.map(str::to_owned).collect();
        let candidates = suggest::Candidates::new(names.iter().map(String::as_str));
        Self { names, candidates }
    }

    fn closest(&self, name: &str) -> Option<String> {
        self.candidates.closest(name).map(|i| self.names[i].clone())
    }
}

#[cfg(test)]
thread_local! {
    /// The catalog scans on this thread: [`scans`].
    static SCANS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// Counts one scan of a catalog's rows by name, in tests (ADR 0014 §7).
#[inline]
fn count_scan() {
    #[cfg(test)]
    SCANS.set(SCANS.get() + 1);
}

/// How many times this thread scanned a catalog's rows for a name or a
/// suggestion.
#[cfg(test)]
pub(crate) fn scans() -> usize {
    SCANS.get()
}

/// A stack version such as `9.2`. Patch numbers are dropped.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct StackVersion {
    pub major: u32,
    pub minor: u32,
}

impl StackVersion {
    pub const fn new(major: u32, minor: u32) -> Self {
        Self { major, minor }
    }

    pub(crate) fn parse(text: &str) -> Option<Self> {
        let text = text.trim().trim_start_matches('=').trim_end_matches('+');
        let text = text.split('-').next()?;
        let mut parts = text.split('.');
        let major = parts.next()?.trim().parse().ok()?;
        let minor = parts.next().unwrap_or("0").trim().parse().ok()?;
        Some(Self { major, minor })
    }
}

impl std::fmt::Display for StackVersion {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}.{}", self.major, self.minor)
    }
}

/// The opentide floor for Elastic Security ([elastic-1.0] "Kibana 8.19 and 9.x").
///
/// 8.19 shipped beside 9.1 with the same ES|QL feature set, so anything the
/// docs first list at 9.2 or later is missing on 8.19. The 9.x docs start at
/// 9.0; a lifecycle that starts at 9.0 or 9.1 says nothing about 8.19.
pub const FIRST_AFTER_FLOOR: StackVersion = StackVersion::new(9, 2);

/// The `stack:` lifecycle of a command or function in the 9.x docs.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Lifecycle {
    /// First version documented as GA. `None` with `ga_unversioned` means
    /// GA in every documented version.
    pub ga: Option<StackVersion>,
    pub ga_unversioned: bool,
    /// First version documented as technical preview.
    pub preview: Option<StackVersion>,
    pub preview_unversioned: bool,
}

impl Lifecycle {
    /// Parse `preview =9.2, ga 9.3+`, `preview 9.1-9.3, ga 9.4+`, `ga`, `ga 9.4.0`.
    pub fn parse(stack: &str) -> Self {
        #[cfg(test)]
        crate::version::count_read();
        let mut lifecycle = Lifecycle::default();
        for entry in stack.split(',') {
            let mut words = entry.split_whitespace();
            let Some(state) = words.next() else {
                continue;
            };
            let version = words.next().and_then(StackVersion::parse);
            match (state, version) {
                ("ga", Some(v)) => lifecycle.ga = Some(lifecycle.ga.map_or(v, |g| g.min(v))),
                ("ga", None) => lifecycle.ga_unversioned = true,
                ("preview" | "beta", Some(v)) => {
                    lifecycle.preview = Some(lifecycle.preview.map_or(v, |p| p.min(v)));
                }
                ("preview" | "beta", None) => lifecycle.preview_unversioned = true,
                _ => {}
            }
        }
        lifecycle
    }

    /// The first version the docs list at all.
    pub fn first(&self) -> Option<StackVersion> {
        match (self.ga, self.preview) {
            (Some(g), Some(p)) => Some(g.min(p)),
            (g, p) => g.or(p),
        }
    }

    pub fn is_ga(&self) -> bool {
        self.ga.is_some() || self.ga_unversioned
    }

    /// Missing on the 8.19 floor: first documented at 9.2 or later.
    pub fn after_floor(&self) -> Option<StackVersion> {
        if self.ga_unversioned || self.preview_unversioned {
            return None;
        }
        self.first().filter(|v| *v >= FIRST_AFTER_FLOOR)
    }

    /// One line for hover text.
    pub fn describe(&self) -> String {
        let mut parts = Vec::new();
        if let Some(p) = self.preview {
            parts.push(format!("technical preview from {p}"));
        } else if self.preview_unversioned && !self.is_ga() {
            parts.push("technical preview".to_string());
        }
        if let Some(g) = self.ga {
            parts.push(format!("GA from {g}"));
        } else if self.ga_unversioned {
            parts.push("GA".to_string());
        }
        parts.join(", ")
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde::Deserialize;

    fn commands_toml() -> &'static str {
        opentide_dataset::text!("data/catalogs/esql/commands.toml")
    }
    fn functions_toml() -> &'static str {
        opentide_dataset::text!("data/catalogs/esql/functions.toml")
    }
    fn operators_toml() -> &'static str {
        opentide_dataset::text!("data/catalogs/esql/operators.toml")
    }
    fn types_toml() -> &'static str {
        opentide_dataset::text!("data/catalogs/esql/types.toml")
    }

    #[derive(Deserialize)]
    struct CommandsFile {
        #[serde(default)]
        branches: Vec<String>,
        commands: Vec<CommandRow>,
    }

    #[derive(Deserialize)]
    struct FunctionsFile {
        #[serde(default)]
        branches: Vec<String>,
        functions: Vec<FunctionRow>,
    }

    #[derive(Deserialize)]
    struct OperatorsFile {
        operators: Vec<OperatorRow>,
    }

    #[derive(Deserialize)]
    struct TypesFile {
        #[serde(default)]
        branches: Vec<String>,
        types: Vec<TypeRow>,
    }

    /// Every name of the catalog, its aliases, in three cases, and near
    /// misses of each: what a query may write.
    fn probes(catalog: &Catalog) -> Vec<String> {
        let mut names: Vec<String> = catalog.commands.iter().map(|c| c.name.clone()).collect();
        for f in &catalog.functions {
            names.push(f.name.clone());
            names.extend(f.aliases.iter().cloned());
        }
        names.extend(catalog.types.iter().map(|t| t.name.clone()));
        let mut out = Vec::new();
        for name in names {
            out.push(name.to_ascii_uppercase());
            let mixed: String = name
                .chars()
                .enumerate()
                .map(|(i, c)| {
                    if i % 2 == 0 {
                        c.to_ascii_uppercase()
                    } else {
                        c
                    }
                })
                .collect();
            out.push(mixed);
            out.push(name[1..].to_owned());
            out.push(format!("{name}x"));
            out.push(format!("_{name}"));
            out.push(name.replace('_', ""));
            out.push(name.chars().rev().collect());
            out.push(name);
        }
        out.extend(["", " ", "\u{e9}val", "EVAL\u{e9}", "to_\u{130}nteger"].map(str::to_owned));
        out
    }

    /// The name indexes find what a scan finds, the same row (ADR 0014 §2).
    #[test]
    fn the_name_indexes_find_what_a_scan_finds() {
        let catalog = Catalog::cached();
        let mut found = 0;
        for name in probes(catalog) {
            let scanned = catalog
                .commands
                .iter()
                .find(|c| c.name.eq_ignore_ascii_case(&name));
            assert!(
                std::ptr::eq(
                    catalog
                        .command(&name)
                        .map_or(std::ptr::null(), std::ptr::from_ref),
                    scanned.map_or(std::ptr::null(), std::ptr::from_ref)
                ),
                "command {name:?}"
            );
            let scanned = catalog.functions.iter().find(|f| {
                f.name.eq_ignore_ascii_case(&name)
                    || f.aliases.iter().any(|a| a.eq_ignore_ascii_case(&name))
            });
            assert!(
                std::ptr::eq(
                    catalog
                        .function(&name)
                        .map_or(std::ptr::null(), std::ptr::from_ref),
                    scanned.map_or(std::ptr::null(), std::ptr::from_ref)
                ),
                "function {name:?}"
            );
            found += usize::from(scanned.is_some());
            let scanned = catalog
                .types
                .iter()
                .find(|t| t.name.eq_ignore_ascii_case(&name));
            assert!(
                std::ptr::eq(
                    catalog
                        .cast_type(&name)
                        .map_or(std::ptr::null(), std::ptr::from_ref),
                    scanned.map_or(std::ptr::null(), std::ptr::from_ref)
                ),
                "type {name:?}"
            );
        }
        assert!(found > 500, "{found}");
    }

    /// The prepared suggestions are the scan's (ADR 0014 §2).
    #[test]
    fn the_prepared_suggestions_are_the_scans() {
        let catalog = Catalog::cached();
        let commands = || {
            catalog
                .commands
                .iter()
                .filter(|c| !c.snapshot_only && c.alias_of.is_none())
                .map(|c| c.name.as_str())
        };
        let functions = || {
            catalog
                .functions
                .iter()
                .filter(|f| !f.snapshot_only)
                .map(|f| f.name.as_str())
        };
        let types = || catalog.types.iter().map(|t| t.name.as_str());
        let mut suggested = 0;
        for name in probes(catalog) {
            let scan = |names: &mut dyn Iterator<Item = &str>| {
                suggest::closest(&name, names).map(str::to_owned)
            };
            assert_eq!(
                catalog.suggest_command(&name),
                scan(&mut commands()),
                "{name:?}"
            );
            let function = catalog.suggest_function(&name);
            assert_eq!(function, scan(&mut functions()), "{name:?}");
            assert_eq!(catalog.suggest_type(&name), scan(&mut types()), "{name:?}");
            suggested += usize::from(function.is_some());
        }
        assert!(suggested > 500, "{suggested}");
    }

    /// A bundled row is read once; any other row, a changed clone included,
    /// is read as it is (ADR 0014 §2).
    #[test]
    fn only_the_bundled_rows_are_read_once() {
        let catalog = Catalog::cached();
        for (i, row) in catalog.functions.iter().enumerate() {
            assert_eq!(index_in(&catalog.functions, row), Some(i));
            assert_eq!(
                row.availability(),
                row.versions.as_deref().map(Availability::from_versions)
            );
            assert_eq!(row.lifecycle(), Lifecycle::parse(&row.stack));
        }
        for (i, row) in catalog.commands.iter().enumerate() {
            assert_eq!(index_in(&catalog.commands, row), Some(i));
            assert_eq!(row.lifecycle(), Lifecycle::parse(&row.stack));
        }
        for row in &catalog.types {
            assert_eq!(
                row.availability(),
                Availability::from_versions(&row.versions)
            );
        }
        let bundled = catalog.function("to_lower").expect("a bundled function");
        let mut changed = bundled.clone();
        assert_eq!(index_in(&catalog.functions, &changed), None);
        changed.versions = Some(vec!["9.6".to_owned()]);
        changed.stack = "preview 9.6".to_owned();
        assert_eq!(
            changed.availability(),
            Some(Availability::from_versions(&["9.6"]))
        );
        assert_ne!(changed.availability(), bundled.availability());
        assert_eq!(changed.lifecycle(), Lifecycle::parse("preview 9.6"));
        let mut cast = catalog
            .cast_type("keyword")
            .expect("a bundled type")
            .clone();
        cast.versions = vec!["8.19".to_owned()];
        assert_eq!(cast.availability(), Availability::ONLY_8_19);
    }

    /// What the build stored is the whole-file parse, field for field (#1743).
    #[test]
    fn the_stored_catalogs_are_the_whole_files() {
        let (branches, commands, functions, operators, types) = model();
        let whole_commands: CommandsFile = toml::from_str(commands_toml()).unwrap();
        let whole_functions: FunctionsFile = toml::from_str(functions_toml()).unwrap();
        let whole_operators: OperatorsFile = toml::from_str(operators_toml()).unwrap();
        let whole_types: TypesFile = toml::from_str(types_toml()).unwrap();
        assert_eq!(branches, whole_commands.branches);
        assert_eq!(branches, whole_functions.branches);
        assert_eq!(branches, whole_types.branches);
        assert_eq!(
            format!("{commands:?}"),
            format!("{:?}", whole_commands.commands)
        );
        assert_eq!(
            format!("{functions:?}"),
            format!("{:?}", whole_functions.functions)
        );
        assert_eq!(
            format!("{operators:?}"),
            format!("{:?}", whole_operators.operators)
        );
        assert_eq!(format!("{types:?}"), format!("{:?}", whole_types.types));
    }

    #[test]
    fn catalog_loads_commands_and_functions() {
        let catalog = Catalog::cached();
        assert!(catalog.command("where").is_some());
        assert!(catalog.command("LOOKUP JOIN").is_some());
        assert!(catalog.function("starts_with").is_some());
        assert!(catalog.function("COUNT").is_some());
        assert_eq!(
            catalog.function("TO_STR").map(|f| f.name.as_str()),
            Some("to_string")
        );
        assert_eq!(
            catalog.function("bin").map(|f| f.name.as_str()),
            Some("bucket")
        );
        assert!(catalog.operator("==").is_some());
        assert_eq!(catalog.suggest_command("wehre").as_deref(), Some("where"));
        // The shared rule: the same word without `_` first, and no
        // suggestion three edits from a three-letter word (`whr` is not `mmr`).
        assert_eq!(
            catalog.suggest_function("tolower").as_deref(),
            Some("to_lower")
        );
        assert_eq!(catalog.suggest_command("whr"), None);
        assert_eq!(catalog.suggest_type("keywrd").as_deref(), Some("keyword"));
        assert!(catalog.function("abs").is_some(), "math module definitions");
        assert_eq!(
            catalog.cast_type("STRING").map(|t| t.function.as_str()),
            Some("to_string")
        );
    }

    #[test]
    fn versions_cover_the_tracked_releases() {
        use crate::version::RELEASES;
        let catalog = Catalog::cached();
        let tracked: Vec<String> = RELEASES.iter().map(ToString::to_string).collect();
        assert_eq!(catalog.branches, tracked);
        let v = |s: &str| StackVersion::parse(s).unwrap();
        let fork = catalog.command("fork").and_then(CommandRow::availability);
        assert!(fork.is_some_and(|a| !a.contains(v("8.19")) && a.contains(v("9.1"))));
        let sample = catalog.command("sample").and_then(CommandRow::availability);
        assert!(sample.is_some_and(|a| a.contains(v("8.19")) && !a.contains(v("9.0"))));
        let copy_sign = catalog
            .function("copy_sign")
            .and_then(FunctionRow::availability);
        assert!(copy_sign.is_some_and(|a| !a.contains(v("8.19")) && a.contains(v("9.1"))));
        let multi_match = catalog
            .function("multi_match")
            .and_then(FunctionRow::availability);
        assert!(multi_match.is_some_and(|a| a.contains(v("9.3")) && !a.contains(v("9.4"))));
        for f in &catalog.functions {
            assert!(!f.docs.is_empty(), "{} has no summary", f.name);
            assert!(f.versions.is_some(), "{} has no versions", f.name);
        }
        for c in &catalog.commands {
            assert!(c.versions.is_some(), "{} has no versions", c.name);
        }
    }

    #[test]
    fn lifecycle_parses_doc_forms() {
        let l = Lifecycle::parse("preview =9.2, ga 9.3+");
        assert_eq!(l.preview, Some(StackVersion::new(9, 2)));
        assert_eq!(l.ga, Some(StackVersion::new(9, 3)));
        assert_eq!(l.after_floor(), Some(StackVersion::new(9, 2)));
        let l = Lifecycle::parse("preview 9.0-9.3, ga 9.4+");
        assert_eq!(l.first(), Some(StackVersion::new(9, 0)));
        assert_eq!(l.after_floor(), None, "9.0 says nothing about 8.19");
        let l = Lifecycle::parse("ga");
        assert!(l.is_ga());
        assert_eq!(l.after_floor(), None);
        let l = Lifecycle::parse("ga 9.4.0");
        assert_eq!(l.ga, Some(StackVersion::new(9, 4)));
        assert_eq!(l.describe(), "GA from 9.4");
        let l = Lifecycle::parse("ga 9.3+, preview 9.1-9.2");
        assert_eq!(l.describe(), "technical preview from 9.1, GA from 9.3");
    }
}
